"""Regenerate LICENSE.tokenizers with desktop Rust dependency notices."""

from __future__ import annotations

import json
import re
import subprocess
from pathlib import Path

ROOT = Path(__file__).resolve().parent
OUTPUT = ROOT / "LICENSE.tokenizers"
MARKER = "RUST TRANSITIVE DEPENDENCY LICENSES AND NOTICES"
TARGETS = (
    "x86_64-pc-windows-msvc",
    "x86_64-unknown-linux-gnu",
    "aarch64-apple-darwin",
)
LICENSE_PREFIXES = ("LICENSE", "LICENCE", "COPYING", "COPYRIGHT", "NOTICE", "UNLICENSE")


def cargo(*args: str) -> str:
    return subprocess.check_output(
        ["cargo", *args, "--manifest-path", str(ROOT / "Cargo.toml")],
        text=True,
    )


def main() -> None:
    used = set()
    for target in TARGETS:
        tree = cargo(
            "tree", "--locked", "--target", target, "--prefix", "none",
            "--format", "{p}", "--edges", "normal,build",
        )
        for line in tree.splitlines():
            match = re.match(r"(.+?) v([^ ]+)", line)
            if match:
                used.add(match.groups())

    metadata = json.loads(cargo("metadata", "--format-version", "1", "--locked"))
    packages = [
        package for package in metadata["packages"]
        if package.get("source") and (package["name"], package["version"]) in used
        and package["name"] != "tokenizers"
    ]
    packages.sort(key=lambda package: (package["name"], package["version"]))

    current = OUTPUT.read_text(encoding="utf-8")
    direct_license = current.split(MARKER, 1)[0].rstrip()
    sections = [
        direct_license,
        MARKER,
        "Generated by generate_notices.py for the Windows, Linux, and macOS dependency union.",
    ]
    for package in packages:
        root = Path(package["manifest_path"]).parent
        files = sorted(
            path for path in root.iterdir()
            if path.is_file() and path.name.upper().startswith(LICENSE_PREFIXES)
        )
        if not files:
            raise RuntimeError(f"No license file for {package['name']} {package['version']}")
        for path in files:
            license_text = path.read_text(encoding="utf-8-sig")
            license_text = "\n".join(line.rstrip() for line in license_text.splitlines()).strip()
            sections.extend([
                "=" * 80,
                f"{package['name']} {package['version']} — {path.name}",
                f"Declared license: {package.get('license') or 'unspecified'}",
                "=" * 80,
                license_text,
            ])

    with OUTPUT.open("w", encoding="utf-8", newline="\n") as output:
        output.write("\n\n".join(sections) + "\n")
    print(f"Wrote notices for {len(packages)} transitive packages to {OUTPUT}")


if __name__ == "__main__":
    main()
